INSERT INTO asgard_catalog.roadmaps (id, title, description, career_id, status, revision_note) VALUES ('67a93b47-ddef-5042-b0cc-33a225888458', 'Machine Learning Engineer: beginner foundations and starter project', 'Intended learner
